import express from 'express';
const app = express();
app.use(express.json());
const TARIFA_KG = 1200;     // pesos por kilo (inventado)
const TARIFA_BULTO = 300;   // pesos por bulto (inventado)
let siguiente = 1;
const tabla = [];

app.post('/envios', (req, res) => {
  const e = { id: siguiente++, estado: 'pendiente', costo_interno: 0, ...req.body };
  e.destino = e.destino.trim().toUpperCase();
  e.tarifa = e.peso_kg * TARIFA_KG + e.bultos * TARIFA_BULTO;
  tabla.push(e);
  res.status(201).json(e);
});
app.listen(19707, '127.0.0.1');

