import { z } from 'zod';

const EnvioEntrada = z.strictObject({
  destino: z.string().trim().min(2).max(60),
  peso_kg: z.number().min(0.001).max(30000),
  bultos: z.number().int().min(1).max(500),
  ventana: z.enum(['manana', 'tarde']).default('manana'),
});

app.post('/envios', (req, res) => {
  const r = EnvioEntrada.safeParse(req.body);
  if (!r.success) {
    return res.status(422).json({ errores: r.error.issues.map((i) => ({
      campo: i.path.join('.') || '(cuerpo)', codigo: i.code, mensaje: i.message })) });
  }
  const env = crearEnvio(r.data);      // r.data ya está limpio
  filas.push(aFila(env));
  res.status(201).json(aSalida(filas.length, env));
});

create table envios (
  id        bigint generated always as identity primary key,
  destino   text    not null check (char_length(destino) between 2 and 60),
  peso_g    integer not null check (peso_g between 1 and 30000000),
  bultos    integer not null check (bultos between 1 and 500),
  ventana   text    not null check (ventana in ('manana', 'tarde')),
  estado    text    not null default 'pendiente' check (estado in ('pendiente', 'en_ruta', 'entregado'))
);
